def monotonic(l):
    """
    Checks whether the input (list or string) is monotonically increasing
    or decreasing (strictly, so duplicates cause a False result).

    For a list:
        - Returns (True, sum_of_elements) if strictly monotonic (no duplicates).
        - Returns False otherwise.

    For a string:
        - Returns (True, original_string) if characters are strictly in
          alphabetical or reverse-alphabetical order (no duplicate chars).
        - Returns False otherwise.

    No loops or built-in sorting methods are used; recursion handles the
    traversal instead.
    """

    def _check(seq, index=0, increasing=None):
        # Base case: reached the end (or seq has 0/1 elements) -> monotonic so far
        if index + 1 >= len(seq):
            return True

        a, b = seq[index], seq[index + 1]

        # Any adjacent equal elements => duplicate => not valid
        if a == b:
            return False

        # Determine direction on first comparison
        if increasing is None:
            increasing = a < b

        if increasing and a < b:
            return _check(seq, index + 1, True)
        elif not increasing and a > b:
            return _check(seq, index + 1, False)
        else:
            return False

    if isinstance(l, str):
        if _check(l):
            return True, l
        else:
            return False
    else:
        # assume list (or similar sequence) of comparable elements
        if _check(l):
            return True, sum(l)
        else:
            return False

