def maximum(arr, k):
    """
    Given an array arr of integers (or strings) and a positive integer k, 
    return a sorted list of length k with the maximum k elements in arr,
    sorted in ascending order.
    """
    if k == 0:
        return []

    # Work on a copy so we don't mutate the input
    nums = list(arr)
    result = []

    # Select the k maximum elements by repeatedly finding and removing the max
    # (no built-in sort used)
    for _ in range(k):
