def get_total_number_of_sequences(m, n):
    """
    Count sequences of length n with elements in [1, m] such that
    each next element is >= 2 * previous element.
    """
    if m <= 0 or n <= 0:
        return 0

    # dp[j] = number of valid sequences of current length ending with value j
    dp = [0] * (m + 1)
    for j in range(1, m + 1):
        dp[j] = 1  # sequences of length 1

    for _ in range(2, n + 1):
        new_dp = [0] * (m + 1)
        prefix_sum = [0] * (m + 1)
        for k in range(1, m + 1):
            prefix_sum[k] = prefix_sum[k - 1] + dp[k]

        for j in range(1, m + 1):
            k_max = j // 2
            if k_max >= 1:
                new_dp[j] = prefix_sum[k_max]
            else:
                new_dp[j] = 0

        dp = new_dp

    return sum(dp[1:m + 1])

