def next_smallest_palindrome(n):
    def is_palindrome(s):
        return s == s[::-1]

    def increment_middle(num_str):
        num_list = list(num_str)
        length = len(num_list)
        mid = length // 2

        if length % 2 == 0:
            left = mid - 1
            right = mid
        else:
            left = mid - 1
            right = mid + 1
            # middle digit itself needs increment handling too
            mid_digit = int(num_list[mid])
            if mid_digit == 9:
                num_list[mid] = '0'
                carry = 1
            else:
                num_list[mid] = str(mid_digit + 1)
                carry = 0
                for i in range(mid+1, length):
                    num_list[i] = num_list[length - 1 - i]
                return ''.join(num_list)

        carry = 1
        while left >= 0 and carry:
            digit = int(num_list[left])
            if digit == 9:
                num_list[left] = '0'
                num_list[right] = '0'
                carry = 1
            else:
                num_list[left] = str(digit + 1)
                num_list[right] = str(digit + 1)
                carry = 0
            left -= 1
            right += 1

        if carry:
            num_list = ['1'] + num_list[:-1] + ['1']

        return ''.join(num_list)

    n_str = str(n)
    length = len(n_str)

    # handle all 9's case separately (next palindrome is 10...01)
    if n_str == '9' * length:
        return int('1' + '0' * (length - 1) + '1')

    # mirror the left half onto the right half
    mid = length // 2
    left_half = n_str[:mid]
    if length % 2 == 0:
        candidate = left_half + left_half[::-1]
    else:
        candidate = left_half + n_str[mid] + left_half[::-1]

    candidate_num = int(candidate)

    if candidate_num > n:
        return candidate_num
    else:
        # need to increment the middle and mirror again
        new_candidate = increment_middle(candidate)
        return int(new_candidate)

