def find_solution(a, b, n):
    """
    Find integers x, y satisfying a*x + b*y = n.

    Preference order:
      1. If a non-negative solution (x >= 0, y >= 0) exists, return it.
      2. Otherwise, if any integer solution exists, return that.
      3. If no integer solution exists at all (gcd(a,b) does not divide n),
         return None.

    Returns:
        (x, y) tuple of ints, or None if no solution exists.
    """
    # Handle degenerate cases where a or b is zero
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        return None

    if a == 0:
        # b*y = n
        if n % b != 0:
            return None
        y = n // b
        x = 0
        if y >= 0:
            return (x, y)
        return (x, y)

    if b == 0:
        if n % a != 0:
            return None
        x = n // a
        y = 0
        if x >= 0:
            return (x, y)
        return (x, y)

    # Extended Euclidean algorithm to find gcd and coefficients
    def extended_gcd(a, b):
        old_r, r = a, b
        old_s, s = 1, 0
        old_t, t = 0, 1
        while r != 0:
            quotient = old_r // r
            old_r, r = r, old_r - quotient * r
            old_s, s = s, old_s - quotient * s
            old_t, t = t, old_t - quotient * t
        return old_r, old_s, old_t  # gcd, x, y such that a*x+b*y=gcd

    g, x0, y0 = extended_gcd(a, b)

    if n % g != 0:
        return None  # no integer solution exists

    scale = n // g
    x0 *= scale
    y0 *= scale

    # General solution: x = x0 + (b/g)*t, y = y0 - (a/g)*t
    step_x = b // g
    step_y = a // g

    # Try to find a non-negative solution by solving inequalities for t
    # x0 + step_x*t >= 0  and  y0 - step_y*t >= 0

    # Determine valid range for t based on sign of step_x and step_y
    import math

    t_lower = -math.inf
    t_upper = math.inf

    if step_x > 0:
        t_lower = max(t_lower, math.ceil(-x0 / step_x))
    elif step_x < 0:
        t_upper = min(t_upper, math.floor(-x0 / step_x))
    else:
        # step_x == 0, x0 must already be >= 0
        if x0 < 0:
            # no non-negative x possible
            t_lower = math.inf
            t_upper = -math.inf

    if step_y > 0:
        t_upper = min(t_upper, math.floor(y0 / step_y))
    elif step_y < 0:
        t_lower = max(t_lower, math.ceil(y0 / step_y))
    else:
        if y0 < 0:
            t_lower = math.inf
            t_upper = -math.inf

    if t_lower <= t_upper and t_lower != math.inf and t_upper != -math.inf:
        # Pick an integer t in [t_lower, t_upper]
        if t_lower == -math.inf:
            t = t_upper
        elif t_upper == math.inf:
            t = t_lower
        else:
            t = t_lower

        t = int(t)
        x = x0 + step_x * t
        y = y0 - step_y * t

        # Double check non-negativity (guard against rounding issues)
        if x >= 0 and y >= 0:
            return (x, y)

        # Fallback search in a small neighborhood if rounding caused issues
        for dt in range(-2, 3):
            tt = t + dt
            xx = x0 + step_x * tt
            yy = y0 - step_y * tt
            if xx >= 0 and yy >= 0:
                return (xx, yy)

    # No non-negative solution found; return the particular integer solution
    return (x0, y0)

