def dict_depth(d):
    """
    Find the depth of a dictionary, treating nested dictionaries,
    lists, and tuples as contributing to the depth measure.

    - A non-container value has depth 0.
    - An empty dict/list/tuple has depth 1.
    - A non-empty dict/list/tuple has depth 1 + max depth of its contained elements
      (values for dicts, items for lists/tuples).
    """
    if isinstance(d, dict):
        if not d:
            return 1
        return 1 + max(dict_depth(v) for v in d.values())
    elif isinstance(d, (list, tuple)):
        if not d:
            return 1
        return 1 + max(dict_depth(v) for v in d)
    else:
        return 0

