def compute_Last_Digit(A, B):
    """
    Find the last digit of (factorial of B) / (factorial of A),
    i.e., the last digit of the product (A+1) * (A+2) * ... * B.
    """
    if A == B:
        return 1
    elif (B - A) >= 5:
        # Among any 5 consecutive integers, there will be a multiple of 2 and 5,
        # making the product's last digit 0.
        return 0
    else:
        result = 1
        for i in range(A + 1, B + 1):
            result = (result * (i % 10)) % 10
        return result % 10

