def next_smallest_palindrome(n):
    """
    Find the smallest palindrome strictly greater than n.

    Args:
        n: A non-negative integer.

    Returns:
        The smallest palindrome number strictly greater than n.
    """
    def is_palindrome(num_str):
        return num_str == num_str[::-1]

    num_str = str(n)
    length = len(num_str)

    # Handle numbers consisting of all 9's (e.g., 9, 99, 999)
    if num_str == '9' * length:
        return int('1' + '0' * (length - 1) + '1')

    digits = list(num_str)
    mid = length // 2

    # Create the left half mirrored to the right half
    if length % 2 == 0:
        left = digits[:mid]
        right = left[::-1]
        candidate = left + right
    else:
        left = digits[:mid]
        right = left[::-1]
        candidate = left + [digits[mid]] + right

    candidate_num = int(''.join(candidate))

    if candidate_num > n:
        return candidate_num

    # Need to increment the middle and mirror again
    if length % 2 == 0:
        # increment the left half as a number
        left_num = int(''.join(left)) + 1
        left_str = str(left_num)
        if len(left_str) > mid:
            # overflow, e.g., 99 -> 100, length increases
            new_length = length + 1
            return int('1' + '0' * (new_length - 2) + '1')
        left_str = left_str.zfill(mid)
        new_candidate = left_str + left_str[::-1]
        return int(new_candidate)
    else:
        mid_digit = int(digits[mid]) + 1
        if mid_digit == 10:
            # carry over to the left part
            left_num = int(''.join(left)) + 1 if left else 1
            left_str = str(left_num)
            if len(left_str) > mid:
                # overflow case
                new_length = length + 1
                return int('1' + '0' * (new_length - 2) + '1')
            left_str = left_str.zfill(mid)
            new_candidate = left_str + '0' + left_str[::-1]
            return int(new_candidate)
        else:
            new_candidate = ''.join(left) + str(mid_digit) + ''.join(left[::-1])
            return int(new_candidate)

