    """
    Find integer values x, y (non-negative) that satisfy ax + by = n.
    Returns a tuple (x, y) if a solution exists, otherwise None.
    """
    for x in range(n + 1):
        remaining = n - a * x
        if remaining < 0:
            break
        if b != 0 and remaining % b == 0:
            y = remaining // b
            if y >= 0:
                return (x, y)
        elif b == 0 and remaining == 0:
            return (x, 0)
    return None

