def get_total_number_of_sequences(N, K):
    """
    Count the number of strictly increasing ordered sequences
    (a_1, a_2, ..., a_K) with values in [1, N] such that each
    subsequent term is at least twice the previous term:
        a_{i+1} >= 2 * a_i   for all i = 1, ..., K-1

    This matches the example: N=10, K=4 -> 4
    (the valid sequences are 1,2,4,8 ; 1,2,4,9 ; 1,2,4,10 ; 1,2,5,10)
    """
    if K <= 0:
        return 0
    if N <= 0:
        return 0
    if K == 1:
        return N

    # dp[v] = number of valid sequences of the current length ending exactly at value v
    dp = [0] * (N + 1)
    for v in range(1, N + 1):
        dp[v] = 1  # sequences of length 1

    for length in range(2, K + 1):
        # prefix sums of dp to quickly sum dp[1..limit]
        prefix = [0] * (N + 2)
        for v in range(1, N + 1):
            prefix[v] = prefix[v - 1] + dp[v]

        new_dp = [0] * (N + 1)
        for v in range(1, N + 1):
            limit = v // 2  # need previous value p such that 2*p <= v  => p <= v//2
            if limit >= 1:
                new_dp[v] = prefix[limit]
            else:
                new_dp[v] = 0
        dp = new_dp

    return sum(dp[1:])

