def find_solution(a, b, n):
    """
    Find integers x and y such that a*x + b*y = n.
    Uses the Extended Euclidean Algorithm.

    Returns:
        (x, y) tuple of integers satisfying a*x + b*y = n,
        or None if no integer solution exists.
    """

    def extended_gcd(a, b):
        # returns (g, x, y) such that a*x + b*y = g = gcd(a, b)
        if b == 0:
            return (a, 1, 0)
        g, x1, y1 = extended_gcd(b, a % b)
        x = y1
        y = x1 - (a // b) * y1
        return (g, x, y)

    # Handle special case a = b = 0
    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)
        else:
            return None

    g, x0, y0 = extended_gcd(a, b)

    if n % g != 0:
        return None  # No solution exists

    scale = n // g
    x = x0 * scale
    y = y0 * scale

    return (x, y)


