def find_Max(arr, low, high):
    if high < low:
        return arr[-1]
    if high == low:
        return arr[low]

    mid = (low + high) // 2

    if mid < high and arr[mid] > arr[mid + 1]:
        return arr[mid]

    if mid > low and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]

    if arr[low] > arr[mid]:
        return find_Max(arr, low, mid - 1)
    else:
        return find_Max(arr, mid + 1, high)

def sum_Of_product(n):
    C = [0] * (n + 2)
    C[0] = 1
    sum = 0
    for i in range(1, n + 1):
        for j in range(i, 0, -1):
            C[j] = C[j] + C[j - 1]
    for i in range(0, n):
        sum += C[i] * C[i + 1]
    return sum

def move_num(test_str):
    res = ''
    dig = ''
    for ele in test_str:
        if ele.isdigit():
            dig += ele
        else:
            res += ele
    res += dig
    return res

def even_Power_Sum(n):
    sum = 0
    for i in range(1, n + 1):
        x = 2 * i
        sum = sum + (x ** 4)
    return sum

def recur_gcd(a, b):
    a, b = abs(a), abs(b)
    if b == 0:
        return a
    return recur_gcd(b, a % b)

