def is_triangleexists(a, b, c):
    if a <= 0 or b <= 0 or c <= 0:
        return False
    return (a + b + c) == 180

def check_Even_Parity(x):
    parity = 0
    while x:
        parity ^= (x & 1)
        x >>= 1
    return parity == 0

def length_Of_Last_Word(s):
    words = s.strip().split()
    if not words:
        return 0
    return len(words[-1])

def lcm(a, b):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x
    return abs(a * b) // gcd(a, b)

def div_of_nums(nums, m, n):
    result = list(filter(lambda x: (x % m == 0 and x % n == 0), nums))
    return result

def substract_elements(test_tup1, test_tup2):
    """
    Subtracts the elements of two given nested tuples element-wise.
    Each tuple is expected to contain tuples of numbers of the same length.
    """
    res = tuple(
        tuple(a - b for a, b in zip(tup1, tup2))
        for tup1, tup2 in zip(test_tup1, test_tup2)
    )
    return res

def get_noOfways(n):
    if n == 0:
        return 0
    if n == 1:
        return 1
    return get_noOfways(n - 1) + get_noOfways(n - 2)
